from __future__ import annotations

HTML = r'''<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="color-scheme" content="light dark">
<title>Memory Box</title>
<style>
:root{
  color-scheme:light;
  --bg:#f5f5f7;--surface:rgba(255,255,255,.78);--surface-solid:#fff;--sidebar:rgba(246,246,248,.82);
  --text:#1d1d1f;--muted:#6e6e73;--faint:#86868b;--line:rgba(0,0,0,.08);--line-strong:rgba(0,0,0,.12);
  --accent:#0071e3;--accent-soft:rgba(0,113,227,.10);--green:#248a3d;--yellow:#b25000;--red:#d70015;
  --shadow:0 12px 40px rgba(0,0,0,.07);--shadow-sm:0 4px 18px rgba(0,0,0,.055);
  --radius:18px;--radius-lg:26px;--radius-sm:12px;
  --font:-apple-system,BlinkMacSystemFont,"SF Pro Text","SF Pro Display","Segoe UI","Microsoft YaHei","Noto Sans CJK SC",sans-serif;
}
html[data-theme="dark"]{
  color-scheme:dark;--bg:#000;--surface:rgba(28,28,30,.78);--surface-solid:#1c1c1e;--sidebar:rgba(22,22,24,.82);
  --text:#f5f5f7;--muted:#a1a1a6;--faint:#8e8e93;--line:rgba(255,255,255,.10);--line-strong:rgba(255,255,255,.16);
  --accent:#0a84ff;--accent-soft:rgba(10,132,255,.15);--green:#30d158;--yellow:#ff9f0a;--red:#ff453a;
  --shadow:0 16px 50px rgba(0,0,0,.30);--shadow-sm:0 6px 24px rgba(0,0,0,.22)
}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:var(--font);font-size:14px}
button,input,select,textarea{font:inherit;color:inherit}button{user-select:none}.app{min-height:100vh;display:grid;grid-template-columns:228px minmax(0,1fr)}
.sidebar{position:sticky;top:0;height:100vh;padding:18px 14px;background:var(--sidebar);border-right:1px solid var(--line);backdrop-filter:saturate(180%) blur(24px);-webkit-backdrop-filter:saturate(180%) blur(24px);z-index:10}
.brand{display:flex;align-items:center;gap:11px;padding:8px 9px 21px}.brand-mark{width:34px;height:34px;border-radius:11px;background:linear-gradient(145deg,#1d1d1f,#56565b);box-shadow:inset 0 0 0 1px rgba(255,255,255,.18),0 4px 12px rgba(0,0,0,.18);display:grid;place-items:center;color:white;font-weight:700;letter-spacing:-1px}.brand-title{font-size:16px;font-weight:650;letter-spacing:-.2px}.brand-sub{font-size:11px;color:var(--muted);margin-top:2px}
.nav{display:flex;flex-direction:column;gap:3px}.nav-section{font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--faint);padding:17px 11px 6px;font-weight:650}.nav button{appearance:none;border:0;background:transparent;width:100%;display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:10px;cursor:pointer;text-align:left;color:var(--muted);font-size:13px;font-weight:500;transition:background .14s ease,color .14s ease,transform .14s ease}.nav button:hover{background:rgba(127,127,127,.09);color:var(--text)}.nav button.active{background:var(--surface-solid);color:var(--text);box-shadow:0 1px 4px rgba(0,0,0,.06)}.nav svg{width:17px;height:17px;stroke:currentColor;stroke-width:1.75;fill:none;stroke-linecap:round;stroke-linejoin:round;flex:none}.nav-spacer{flex:1}.side-footer{position:absolute;left:14px;right:14px;bottom:16px;border-top:1px solid var(--line);padding-top:12px}.side-footer-row{display:flex;align-items:center;gap:8px;padding:5px 8px;color:var(--muted);font-size:11px}.status-dot{width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 0 3px color-mix(in srgb,var(--green) 12%,transparent)}
.shell{min-width:0}.toolbar{position:sticky;top:0;height:66px;display:flex;align-items:center;gap:14px;padding:0 30px;background:color-mix(in srgb,var(--bg) 72%,transparent);border-bottom:1px solid var(--line);backdrop-filter:saturate(180%) blur(22px);-webkit-backdrop-filter:saturate(180%) blur(22px);z-index:9}.toolbar-title{font-weight:650;font-size:15px;min-width:105px}.global-search{flex:1;max-width:540px;position:relative}.global-search svg{position:absolute;width:16px;height:16px;left:12px;top:50%;transform:translateY(-50%);stroke:var(--muted);fill:none;stroke-width:2}.global-search input{width:100%;height:36px;border:1px solid var(--line);background:var(--surface);border-radius:11px;padding:0 12px 0 36px;outline:none;box-shadow:0 1px 2px rgba(0,0,0,.02)}.global-search input:focus{border-color:color-mix(in srgb,var(--accent) 55%,var(--line));box-shadow:0 0 0 3px var(--accent-soft)}.toolbar-actions{margin-left:auto;display:flex;align-items:center;gap:8px}.icon-btn{width:34px;height:34px;border-radius:10px;border:1px solid var(--line);background:var(--surface);display:grid;place-items:center;cursor:pointer}.icon-btn:hover{background:var(--surface-solid)}.icon-btn svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:1.8}.primary-compact{height:34px;border:0;border-radius:10px;background:var(--accent);color:white;padding:0 13px;font-weight:600;cursor:pointer;box-shadow:0 2px 8px color-mix(in srgb,var(--accent) 18%,transparent)}
.content{max-width:1240px;margin:0 auto;padding:36px 34px 80px}.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:26px}.page-head h1{font-size:31px;line-height:1.1;margin:0;letter-spacing:-.75px;font-weight:700}.page-head p{margin:7px 0 0;color:var(--muted);font-size:13px;line-height:1.5}.page-actions{display:flex;gap:8px;flex-wrap:wrap}
.btn{appearance:none;border:0;border-radius:11px;height:38px;padding:0 15px;background:var(--accent);color:white;font-weight:600;cursor:pointer;transition:transform .12s ease,filter .12s ease,background .12s ease;display:inline-flex;align-items:center;justify-content:center;gap:7px;text-decoration:none}.btn:hover{filter:brightness(1.03)}.btn:active{transform:scale(.985)}.btn.secondary{background:var(--surface-solid);color:var(--text);border:1px solid var(--line);box-shadow:0 1px 2px rgba(0,0,0,.025)}.btn.ghost{background:transparent;color:var(--accent);padding-left:9px;padding-right:9px}.btn.danger{background:color-mix(in srgb,var(--red) 11%,var(--surface-solid));color:var(--red);border:1px solid color-mix(in srgb,var(--red) 18%,transparent)}.btn.small{height:31px;padding:0 10px;font-size:12px;border-radius:9px}
.hero-grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(280px,.8fr);gap:16px;margin-bottom:16px}.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow-sm);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)}.hero-card{padding:26px;border-radius:var(--radius-lg);min-height:230px;display:flex;flex-direction:column;justify-content:space-between;overflow:hidden;position:relative}.hero-card:after{content:"";position:absolute;width:220px;height:220px;border-radius:50%;right:-80px;top:-95px;background:radial-gradient(circle,color-mix(in srgb,var(--accent) 18%,transparent),transparent 68%);pointer-events:none}.eyebrow{color:var(--muted);font-size:12px;font-weight:600}.health-value{font-size:52px;line-height:.95;font-weight:720;letter-spacing:-2px;margin:12px 0 8px}.health-value.green{color:var(--green)}.health-value.yellow{color:var(--yellow)}.health-value.red{color:var(--red)}.hero-copy{color:var(--muted);font-size:13px;max-width:580px;line-height:1.6}.quick-card{padding:22px}.quick-card h3,.section-title{font-size:16px;margin:0;font-weight:650;letter-spacing:-.2px}.quick-list{display:grid;gap:9px;margin-top:18px}.quick-action{width:100%;border:0;background:transparent;display:flex;align-items:center;gap:12px;padding:10px;border-radius:12px;cursor:pointer;text-align:left}.quick-action:hover{background:rgba(127,127,127,.08)}.quick-icon{width:34px;height:34px;border-radius:10px;background:var(--accent-soft);color:var(--accent);display:grid;place-items:center;font-size:17px;flex:none}.quick-label{font-weight:600;font-size:13px}.quick-desc{font-size:11px;color:var(--muted);margin-top:2px}
.section-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(280px,.65fr);gap:16px}.section-card{padding:20px}.section-card-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:13px}.subtle-link{border:0;background:transparent;color:var(--accent);font-size:12px;cursor:pointer}.memory-row{display:grid;grid-template-columns:36px minmax(0,1fr) auto;align-items:center;gap:11px;padding:11px 4px;border-top:1px solid var(--line);cursor:pointer}.memory-row:first-of-type{border-top:0}.memory-row:hover .memory-title{color:var(--accent)}.memory-icon{width:34px;height:34px;border-radius:10px;background:rgba(127,127,127,.08);display:grid;place-items:center;color:var(--muted);font-size:13px;font-weight:650}.memory-title{font-weight:600;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;transition:color .12s}.memory-summary{color:var(--muted);font-size:11px;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.memory-time{color:var(--faint);font-size:11px;white-space:nowrap}.metric-list{display:grid;gap:12px;margin-top:15px}.metric{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-top:1px solid var(--line)}.metric:first-child{border-top:0}.metric-label{color:var(--muted);font-size:12px}.metric-value{font-weight:650;font-size:13px}.lock{color:var(--green)}
.filterbar{display:flex;align-items:center;gap:8px;margin-bottom:15px;flex-wrap:wrap}.filterbar input,.filterbar select,.form-row input,.form-row select,.form-row textarea{border:1px solid var(--line);background:var(--surface-solid);border-radius:11px;outline:none}.filterbar input{height:38px;padding:0 12px;min-width:240px;flex:1}.filterbar select{height:38px;padding:0 30px 0 11px}.filterbar input:focus,.filterbar select:focus,.form-row input:focus,.form-row select:focus,.form-row textarea:focus{border-color:color-mix(in srgb,var(--accent) 55%,var(--line));box-shadow:0 0 0 3px var(--accent-soft)}
.memory-table{overflow:hidden}.memory-item{display:grid;grid-template-columns:48px minmax(0,1fr) 120px 92px;align-items:center;gap:14px;padding:14px 18px;border-top:1px solid var(--line)}.memory-item:first-child{border-top:0}.memory-item:hover{background:rgba(127,127,127,.035)}.memory-badge{width:40px;height:40px;border-radius:12px;background:rgba(127,127,127,.08);display:grid;place-items:center;color:var(--muted);font-weight:650;font-size:11px}.memory-main{min-width:0}.memory-main .title{font-size:14px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.memory-main .summary{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:4px}.memory-category{font-size:11px;color:var(--muted)}.memory-actions{display:flex;justify-content:flex-end;gap:5px}.mini-btn{width:30px;height:30px;border:1px solid var(--line);background:transparent;border-radius:9px;cursor:pointer;color:var(--muted);display:grid;place-items:center}.mini-btn:hover{background:var(--surface-solid);color:var(--text)}
.empty{padding:54px 24px;text-align:center;color:var(--muted)}.empty .big{font-size:32px;margin-bottom:10px}.empty h3{color:var(--text);margin:0 0 6px;font-size:16px}
.form-card{padding:24px}.form-card h2{font-size:20px;margin:0 0 6px;letter-spacing:-.35px}.form-card .lead{color:var(--muted);margin:0 0 20px;line-height:1.6}.form-row{display:flex;gap:10px;margin-top:10px;align-items:center}.form-row input,.form-row select{height:40px;padding:0 12px;flex:1}.form-row textarea{width:100%;min-height:170px;resize:vertical;padding:13px;line-height:1.6}.file-drop{margin-top:12px;border:1px dashed var(--line-strong);border-radius:14px;padding:16px;background:rgba(127,127,127,.025)}.helper{font-size:11px;color:var(--muted);line-height:1.55}.notice{padding:12px 14px;border-radius:12px;background:var(--accent-soft);color:color-mix(in srgb,var(--accent) 76%,var(--text));font-size:12px;line-height:1.55}.ok{color:var(--green)}.warn{color:var(--yellow)}.danger-text{color:var(--red)}
.settings-list{overflow:hidden}.setting-row{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:15px 18px;border-top:1px solid var(--line)}.setting-row:first-child{border-top:0}.setting-title{font-weight:600}.setting-desc{font-size:11px;color:var(--muted);margin-top:3px}.segmented{display:flex;padding:2px;border-radius:10px;background:rgba(127,127,127,.10)}.segmented button{border:0;background:transparent;padding:6px 10px;border-radius:8px;cursor:pointer;color:var(--muted);font-size:11px}.segmented button.active{background:var(--surface-solid);color:var(--text);box-shadow:0 1px 4px rgba(0,0,0,.09)}
.modal{position:fixed;inset:0;background:rgba(0,0,0,.28);backdrop-filter:blur(6px);display:none;align-items:center;justify-content:center;padding:24px;z-index:100}.modal-box{background:var(--surface-solid);border:1px solid var(--line);border-radius:22px;box-shadow:0 28px 80px rgba(0,0,0,.25);width:min(820px,100%);max-height:84vh;overflow:auto;padding:22px}.modal-head{display:flex;justify-content:flex-end;position:sticky;top:0;z-index:1}.modal-close{border:0;width:30px;height:30px;border-radius:50%;background:rgba(127,127,127,.12);cursor:pointer;color:var(--muted)}pre{white-space:pre-wrap;word-break:break-word;background:rgba(127,127,127,.07);padding:14px;border-radius:12px;border:1px solid var(--line);font-size:12px;line-height:1.55}.chips{display:flex;gap:5px;flex-wrap:wrap}.chip{font-size:10px;padding:4px 7px;border-radius:999px;background:rgba(127,127,127,.09);color:var(--muted)}.agent-row{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:14px 0;border-top:1px solid var(--line)}.agent-row:first-of-type{border-top:0}.agent-name{font-weight:650}.agent-meta{font-size:11px;color:var(--muted);margin-top:3px}.health-banner{display:grid;grid-template-columns:140px minmax(0,1fr);gap:24px;align-items:center;padding:25px}.health-orb{width:112px;height:112px;border-radius:50%;display:grid;place-items:center;margin:auto;font-size:19px;font-weight:720;border:1px solid var(--line);box-shadow:inset 0 0 0 8px rgba(127,127,127,.04)}.health-orb.green{color:var(--green);background:color-mix(in srgb,var(--green) 8%,var(--surface-solid))}.health-orb.yellow{color:var(--yellow);background:color-mix(in srgb,var(--yellow) 8%,var(--surface-solid))}.health-orb.red{color:var(--red);background:color-mix(in srgb,var(--red) 8%,var(--surface-solid))}
.stack{display:grid;gap:16px}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:16px}.code{font-family:"SFMono-Regular",Consolas,monospace}.toast{position:fixed;right:24px;bottom:24px;background:var(--text);color:var(--bg);padding:11px 14px;border-radius:12px;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.18s ease;z-index:120}.toast.show{opacity:1;transform:translateY(0)}
@media(max-width:980px){.app{grid-template-columns:82px minmax(0,1fr)}.sidebar{padding:17px 10px}.brand{justify-content:center;padding-left:0;padding-right:0}.brand-copy,.nav button span,.nav-section,.side-footer-row span{display:none}.nav button{justify-content:center;padding:10px}.hero-grid,.section-grid{grid-template-columns:1fr}.memory-item{grid-template-columns:44px minmax(0,1fr) 92px}.memory-category{display:none}}
@media(max-width:700px){.app{display:block}.sidebar{position:fixed;left:0;right:0;bottom:0;top:auto;height:64px;border-right:0;border-top:1px solid var(--line);display:flex;padding:7px 8px;z-index:30}.brand,.nav-section,.side-footer{display:none}.nav{width:100%;display:grid;grid-template-columns:repeat(5,1fr);gap:3px}.nav button:nth-of-type(n+6){display:none}.nav button span{display:block;font-size:9px}.nav button{flex-direction:column;gap:2px;padding:5px}.toolbar{padding:0 14px;height:58px}.toolbar-title{display:none}.global-search{max-width:none}.primary-compact{display:none}.content{padding:24px 14px 88px}.page-head{align-items:flex-start}.page-head h1{font-size:27px}.hero-card{min-height:215px;padding:22px}.health-value{font-size:45px}.memory-item{grid-template-columns:42px minmax(0,1fr) 74px;padding:12px}.memory-time{font-size:10px}.memory-actions{display:none}.two-col{grid-template-columns:1fr}.health-banner{grid-template-columns:1fr;text-align:center}.form-row{flex-direction:column;align-items:stretch}}
.project-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.project-card{padding:18px;cursor:pointer;transition:transform .14s ease,box-shadow .14s ease}.project-card:hover{transform:translateY(-1px);box-shadow:0 8px 28px rgba(0,0,0,.07)}.project-name{font-size:17px;font-weight:720;letter-spacing:-.015em}.project-meta{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:10px}.state-pill{display:inline-flex;padding:4px 8px;border-radius:999px;background:var(--surface-solid);border:1px solid var(--line);font-size:11px;color:var(--muted)}.project-continuity{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}.project-continuity .notice{margin:0}.score{font-variant-numeric:tabular-nums;color:var(--accent);font-size:11px;font-weight:700}@media(max-width:800px){.project-grid,.project-continuity{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
</style>
</head>
<body>
<div class="app">
  <aside class="sidebar">
    <div class="brand"><div class="brand-mark">M</div><div class="brand-copy"><div class="brand-title">Memory Box</div><div class="brand-sub">Private AI memory hub</div></div></div>
    <nav class="nav">
      <div class="nav-section">Library</div>
      <button data-view="home" class="active" onclick="view('home')"><svg viewBox="0 0 24 24"><path d="M3 11.5 12 4l9 7.5"/><path d="M5.5 10.5V20h13v-9.5"/><path d="M9 20v-6h6v6"/></svg><span>首页</span></button>
      <button data-view="projects" onclick="view('projects')"><svg viewBox="0 0 24 24"><path d="M4 6.5h6l2 2h8v9.5a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V8.5a2 2 0 0 1 2-2z"/><path d="M8 13h8M8 16h5"/></svg><span>项目</span></button>
      <button data-view="memories" onclick="view('memories')"><svg viewBox="0 0 24 24"><rect x="4" y="4" width="16" height="16" rx="4"/><path d="M8 9h8M8 13h8M8 17h5"/></svg><span>记忆</span></button>
      <button data-view="save" onclick="view('save')"><svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/><circle cx="12" cy="12" r="9"/></svg><span>保存</span></button>
      <div class="nav-section">Continuity</div>
      <button data-view="agents" onclick="view('agents')"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="M8 9h.01M16 9h.01M8 15c1.5 1 6.5 1 8 0"/></svg><span>Agent</span></button>
      <button data-view="sync" onclick="view('sync')"><svg viewBox="0 0 24 24"><path d="M20 7h-9"/><path d="m16 3 4 4-4 4"/><path d="M4 17h9"/><path d="m8 13-4 4 4 4"/></svg><span>同步</span></button>
      <button data-view="insurance" onclick="view('insurance')"><svg viewBox="0 0 24 24"><path d="M12 3 5 6v5c0 4.6 2.8 8 7 10 4.2-2 7-5.4 7-10V6z"/><path d="m9.5 12 1.6 1.6 3.7-4"/></svg><span>保险</span></button>
      <button data-view="recovery" onclick="view('recovery')"><svg viewBox="0 0 24 24"><path d="M4 12a8 8 0 1 0 2.3-5.7L4 8.5"/><path d="M4 4v4.5h4.5"/><path d="M12 8v4l3 2"/></svg><span>恢复</span></button>
      <button data-view="transfer" onclick="view('transfer')"><svg viewBox="0 0 24 24"><path d="M12 3v12"/><path d="m8 7 4-4 4 4"/><path d="M5 13v6h14v-6"/></svg><span>迁移</span></button>
      <div class="nav-section">System</div>
      <button data-view="settings" onclick="view('settings')"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.83 2.83-.06-.06A1.7 1.7 0 0 0 15 19.4a1.7 1.7 0 0 0-1 .6 1.7 1.7 0 0 0-.4 1.1V21h-4v-.09A1.7 1.7 0 0 0 8.6 19.4a1.7 1.7 0 0 0-1.88.34l-.06.06-2.83-2.83.06-.06A1.7 1.7 0 0 0 4.6 15a1.7 1.7 0 0 0-.6-1 1.7 1.7 0 0 0-1.1-.4H3v-4h.09A1.7 1.7 0 0 0 4.6 8.6a1.7 1.7 0 0 0-.34-1.88l-.06-.06 2.83-2.83.06.06A1.7 1.7 0 0 0 9 4.6a1.7 1.7 0 0 0 1-.6 1.7 1.7 0 0 0 .4-1.1V3h4v.09A1.7 1.7 0 0 0 15.4 4a1.7 1.7 0 0 0 1.88-.34l.06-.06 2.83 2.83-.06.06A1.7 1.7 0 0 0 19.4 9c.1.4.3.7.6 1 .3.2.7.4 1.1.4H21v4h-.09c-.4 0-.8.2-1.1.4-.2.1-.3.2-.4.2z"/></svg><span>设置</span></button>
    </nav>
    <div class="side-footer"><div class="side-footer-row"><i class="status-dot"></i><span>Local · v__VERSION__</span></div></div>
  </aside>
  <section class="shell">
    <header class="toolbar">
      <div class="toolbar-title" id="toolbarTitle">首页</div>
      <div class="global-search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg><input id="globalSearch" placeholder="搜索你的记忆" onkeydown="if(event.key==='Enter')globalSearchNow()"></div>
      <div class="toolbar-actions"><button class="icon-btn" title="外观" onclick="cycleTheme()"><svg viewBox="0 0 24 24"><path d="M12 3a9 9 0 1 0 9 9c0-.5-.04-1-.12-1.45A7 7 0 0 1 12 3z"/></svg></button><button class="primary-compact" onclick="view('save')">＋ 保存记忆</button></div>
    </header>
    <main class="content" id="content"></main>
  </section>
</div>
<div class="modal" id="modal" onclick="if(event.target===this)closeModal()"><div class="modal-box"><div class="modal-head"><button class="modal-close" onclick="closeModal()">×</button></div><div id="modalBody"></div></div></div>
<div class="toast" id="toast"></div>
<script>
const A='/api/'; const CATS=__CATEGORIES__; let currentCat='all'; let currentView='home';
const TITLES={home:'首页',projects:'项目',memories:'记忆',save:'保存记忆',agents:'Agent 连接',sync:'设备同步',insurance:'自动保险',recovery:'灾难恢复',transfer:'迁移',settings:'设置'};
async function api(path,opt){const r=await fetch(A+path,opt);const text=await r.text();let j={};try{j=JSON.parse(text)}catch{j={error:text}}if(!r.ok)throw Error(j.error||r.statusText);return j}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function fmtDate(s){if(!s)return '—';try{const d=new Date(s);return new Intl.DateTimeFormat('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)}catch{return s}}
function toastMsg(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function setActive(name){currentView=name;document.getElementById('toolbarTitle').textContent=TITLES[name]||'Memory Box';document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name))}
async function view(name,opts={}){setActive(name);try{if(name==='home')return homeView();if(name==='projects')return projectsView();if(name==='memories')return memoriesView(opts.query||'');if(name==='save')return saveView();if(name==='agents')return agentsView();if(name==='sync')return syncView();if(name==='insurance')return insuranceView();if(name==='recovery')return recoveryView();if(name==='transfer')return transferView();if(name==='settings')return settingsView()}catch(e){document.getElementById('content').innerHTML=`<div class="card empty"><div class="big">!</div><h3>无法加载</h3><div>${esc(e.message)}</div></div>`}}
function globalSearchNow(){const q=document.getElementById('globalSearch').value.trim();view('memories',{query:q})}
function healthClass(s){return s==='GREEN'?'green':s==='YELLOW'?'yellow':'red'}
async function homeView(){const [health,mems,cats,eps,ident,ins,projects,semantic]=await Promise.all([api('insurance/health'),api('memories?limit=6&category=all'),api('categories'),api('sync/endpoints'),api('device/identity'),api('insurance/status'),api('projects?limit=50'),api('semantic/status')]);const total=cats.reduce((a,c)=>a+Number(c.count||0),0);const e2ee=eps.filter(e=>e.e2ee).length;const status=health.status||'RED';const recent=mems.map(m=>`<div class="memory-row" onclick="openMemory('${m.memory_id}')"><div class="memory-icon">${esc(m.memory_id.replace('M',''))}</div><div><div class="memory-title">${esc(m.title)}</div><div class="memory-summary">${esc(m.summary||m.category_label||'')}</div></div><div class="memory-time">${fmtDate(m.updated_at)}</div></div>`).join('')||'<div class="empty"><h3>还没有记忆</h3><div>保存一段对话后，它会出现在这里。</div></div>';
document.getElementById('content').innerHTML=`<div class="page-head"><div><h1>Memory Box</h1><p>你的本地、跨 Agent、跨设备记忆中枢。</p></div><div class="page-actions"><button class="btn secondary" onclick="view('memories')">浏览记忆</button><button class="btn" onclick="view('save')">保存当前内容</button></div></div><div class="hero-grid"><section class="card hero-card"><div><div class="eyebrow">灾难恢复状态</div><div class="health-value ${healthClass(status)}">${esc(status)}</div><div class="hero-copy">${health.recoverable_if_recovery_code_available?'当前自动检查确认：在你仍持有恢复码的前提下，已有可用的恢复链。':'当前恢复链仍有未完成项。建议进入“自动保险”查看阻塞项。'}</div></div><div><button class="btn secondary small" onclick="view('insurance')">查看保险状态</button></div></section><section class="card quick-card"><h3>快捷操作</h3><div class="quick-list"><button class="quick-action" onclick="view('save')"><span class="quick-icon">＋</span><span><div class="quick-label">保存一段记忆</div><div class="quick-desc">聊天、决策、文件与下一步</div></span></button><button class="quick-action" onclick="view('projects')"><span class="quick-icon">◇</span><span><div class="quick-label">继续一个项目</div><div class="quick-desc">恢复状态、下一步与相关记忆</div></span></button><button class="quick-action" onclick="resumeLatest()"><span class="quick-icon">↗</span><span><div class="quick-label">继续最近工作</div><div class="quick-desc">生成最近记忆的 Resume Context</div></span></button><button class="quick-action" onclick="view('transfer')"><span class="quick-icon">⇄</span><span><div class="quick-label">迁移到另一台电脑</div><div class="quick-desc">导入或导出完整会话包</div></span></button></div></section></div><div class="section-grid"><section class="card section-card"><div class="section-card-head"><h3 class="section-title">最近记忆</h3><button class="subtle-link" onclick="view('memories')">查看全部</button></div>${recent}</section><section class="card section-card"><div class="section-card-head"><h3 class="section-title">系统概览</h3></div><div class="metric-list"><div class="metric"><span class="metric-label">记忆总数</span><span class="metric-value">${total}</span></div><div class="metric"><span class="metric-label">活跃项目</span><span class="metric-value">${projects.filter(p=>p.status==='active').length}</span></div><div class="metric"><span class="metric-label">E2EE 同步端点</span><span class="metric-value lock">${e2ee} 个</span></div><div class="metric"><span class="metric-label">本地向量检索</span><span class="metric-value">${semantic.neural?'Neural':'Local Vector'}</span></div><div class="metric"><span class="metric-label">自动保险</span><span class="metric-value">${ins.enabled?'已启用':'未启用'}</span></div><div class="metric"><span class="metric-label">设备指纹</span><span class="metric-value code" title="${esc(ident.fingerprint)}">${esc((ident.fingerprint||'').slice(0,11))}…</span></div></div></section></div>`}
async function resumeLatest(){const m=await api('memories?limit=1&category=all');if(!m.length){toastMsg('还没有可恢复的记忆');return}resumeOne(m[0].memory_id)}
async function memoriesView(initial=''){const cats=await api('categories');document.getElementById('content').innerHTML=`<div class="page-head"><div><h1>记忆</h1><p>搜索、筛选并恢复任何已经保存的上下文。</p></div><div class="page-actions"><button class="btn" onclick="view('save')">＋ 新记忆</button></div></div><div class="filterbar"><input id="q" value="${esc(initial)}" placeholder="搜索标题、正文、标签…" onkeydown="if(event.key==='Enter')loadMemoriesData(this.value)"><select id="catFilter" onchange="currentCat=this.value;loadMemoriesData(q.value)"><option value="all">全部分类</option>${cats.map(c=>`<option value="${esc(c.category)}" ${currentCat===c.category?'selected':''}>${esc(c.label)} · ${c.count}</option>`).join('')}</select><button class="btn secondary" onclick="currentCat='all';catFilter.value='all';q.value='';loadMemoriesData('')">清除</button></div><div class="card memory-table" id="memoryTable"></div>`;await loadMemoriesData(initial)}
async function loadMemoriesData(q=''){const data=q.trim()?await api(`search/smart?limit=100&category=${encodeURIComponent(currentCat)}&query=${encodeURIComponent(q)}`):await api(`memories?limit=100&category=${encodeURIComponent(currentCat)}`);const box=document.getElementById('memoryTable');if(!box)return;if(!data.length){box.innerHTML='<div class="empty"><div class="big">⌕</div><h3>没有找到记忆</h3><div>换一个关键词，或保存新的对话。</div></div>';return}box.innerHTML=data.map(m=>`<div class="memory-item"><div class="memory-badge">${esc(m.memory_id)}</div><div class="memory-main" onclick="openMemory('${m.memory_id}')" style="cursor:pointer"><div class="title">${m.pinned?'⌖ ':''}${m.favorite?'★ ':''}${esc(m.title)}</div><div class="summary">${esc(m.summary||'')}${m.retrieval_score?` · <span class="score">智能相关度 ${Number(m.retrieval_score).toFixed(1)}</span>`:''}</div></div><div class="memory-category">${esc(m.category_label)}<br><span>${fmtDate(m.updated_at)}</span></div><div class="memory-actions"><button class="mini-btn" title="固定" onclick="flag('${m.memory_id}','pinned',${!m.pinned})">⌖</button><button class="mini-btn" title="收藏" onclick="flag('${m.memory_id}','favorite',${!m.favorite})">☆</button><button class="mini-btn" title="继续" onclick="resumeOne('${m.memory_id}')">↗</button></div></div>`).join('')}
async function projectsView(){const ps=await api('projects?limit=200');const cards=ps.map(p=>`<section class="card project-card" onclick="openProject('${p.project_id}')"><div class="helper">${esc(p.project_id)}</div><div class="project-name">${esc(p.name)}</div><p class="memory-summary">${esc(p.summary||p.auto_summary||'还没有项目摘要')}</p><div class="project-meta"><span class="state-pill">${esc(p.status)}</span><span class="state-pill">${p.memory_count} 条记忆</span>${(p.next_action||p.auto_next_action)?`<span class="state-pill">下一步：${esc((p.next_action||p.auto_next_action).slice(0,28))}</span>`:''}</div></section>`).join('')||'<div class="card empty"><div class="big">◇</div><h3>还没有项目</h3><div>创建第一个 Project Workspace，把长期任务从零散记忆提升为可持续工作空间。</div></div>';document.getElementById('content').innerHTML=`<div class="page-head"><div><h1>项目</h1><p>把记忆组织为长期工作空间，并保存当前状态和下一步。</p></div></div><section class="card form-card" style="margin-bottom:16px"><div class="form-row"><input id="projectName" placeholder="项目名称，例如 CRAB Manuscript"><input id="projectSummary" placeholder="一句话目标 / 摘要"><button class="btn" onclick="createProjectNow()">＋ 创建项目</button></div></section><div class="project-grid">${cards}</div>`}
async function createProjectNow(){try{const p=await api('projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:projectName.value,summary:projectSummary.value})});toastMsg(`已创建 ${p.project_id}`);openProject(p.project_id)}catch(e){toastMsg(e.message)}}
async function openProject(id){const p=await api('projects/'+id);const rows=(p.memories||[]).map(m=>`<div class="memory-item"><div class="memory-badge">${esc(m.memory_id)}</div><div class="memory-main" onclick="openMemory('${m.memory_id}')" style="cursor:pointer"><div class="title">${esc(m.title)}</div><div class="summary">${esc(m.summary||'')}</div></div><div class="memory-category"><span>${esc(m.role||'context')}</span><br><span>${fmtDate(m.updated_at)}</span></div><div class="memory-actions"><button class="mini-btn" title="移出项目" onclick="removeProjectMemory('${id}','${m.memory_id}')">×</button></div></div>`).join('')||'<div class="empty"><h3>项目里还没有记忆</h3><div>输入 M000xxx，把已有记忆加入项目。</div></div>';document.getElementById('content').innerHTML=`<div class="page-head"><div><div class="helper">${esc(p.project_id)} · ${esc(p.status)}</div><h1>${esc(p.name)}</h1><p>${esc(p.summary||p.auto_summary||'')}</p></div><div class="page-actions"><button class="btn secondary" onclick="projectsView()">返回项目</button><button class="btn" onclick="resumeProject('${id}')">继续这个项目</button></div></div><div class="project-continuity"><section class="card form-card"><h2>项目状态</h2><div class="form-row"><input id="pSummary" value="${esc(p.summary||'')}" placeholder="项目摘要"><select id="pStatus"><option value="active" ${p.status==='active'?'selected':''}>active</option><option value="paused" ${p.status==='paused'?'selected':''}>paused</option><option value="completed" ${p.status==='completed'?'selected':''}>completed</option></select></div><div class="form-row"><textarea id="pState" placeholder="当前状态">${esc(p.current_state||'')}</textarea></div><div class="form-row"><input id="pNext" value="${esc(p.next_action||'')}" placeholder="下一步行动"><button class="btn" onclick="updateProjectNow('${id}')">保存状态</button></div></section><section class="card form-card"><h2>加入已有记忆</h2><p class="lead">项目不会复制记忆，只建立可迁移的关联。</p><div class="form-row"><input id="projectMemoryId" placeholder="M000007"><input id="projectRole" placeholder="角色，例如 decision / evidence / context" value="context"><button class="btn secondary" onclick="addProjectMemory('${id}')">加入</button></div><div class="page-actions" style="margin-top:10px"><button class="btn secondary small" onclick="suggestProject('${id}')">发现相关记忆</button><button class="btn secondary small" onclick="refreshProject('${id}')">刷新自动摘要</button></div><div class="notice"><b>自动项目摘要</b><br>${esc(p.auto_summary||'加入记忆后自动生成，不覆盖手工摘要。')}<br><span class="helper">自动状态：${esc(p.auto_current_state||'—')} · 自动下一步：${esc(p.auto_next_action||'—')}</span></div></section></div><section class="card memory-table" style="margin-top:16px">${rows}</section>`}
async function updateProjectNow(id){try{await api('projects/'+id,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({summary:pSummary.value,current_state:pState.value,next_action:pNext.value,status:pStatus.value})});toastMsg('项目状态已保存');openProject(id)}catch(e){toastMsg(e.message)}}
async function refreshProject(id){try{await api('projects/'+id+'/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});toastMsg('自动摘要已刷新');openProject(id)}catch(e){toastMsg(e.message)}}
async function addProjectMemory(id){try{await api('projects/'+id+'/memories',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({memory_id:projectMemoryId.value,role:projectRole.value})});toastMsg('记忆已加入项目');openProject(id)}catch(e){toastMsg(e.message)}}
async function removeProjectMemory(id,mid){try{await api('projects/'+id+'/memories',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({memory_id:mid,action:'remove'})});openProject(id)}catch(e){toastMsg(e.message)}}
async function suggestProject(id){try{const xs=await api('projects/'+id+'/suggest?limit=10');showModal(`<h2>建议加入项目的记忆</h2>${xs.length?xs.map(x=>`<div class="memory-row"><div class="memory-icon">${esc(x.memory_id)}</div><div style="flex:1"><div class="memory-title">${esc(x.title)}</div><div class="memory-summary">相关度 ${Number(x.retrieval_score||0).toFixed(1)} · ${esc((x.retrieval_reasons||[]).join(' / '))}</div></div><button class="btn secondary small" onclick="api('projects/${id}/memories',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({memory_id:'${x.memory_id}',role:'context'})}).then(()=>{toastMsg('已加入项目');closeModal();openProject('${id}')})">加入</button></div>`).join(''):'<div class="helper">暂无新的高相关记忆</div>'}`)}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function resumeProject(id){try{const j=await api('projects/'+id+'/resume',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({limit:12})});showModal(`<h2>Project Resume Context</h2><div class="helper">已按项目上下文智能排序 ${j.memory_ids.length} 条记忆。</div><pre>${esc(j.context)}</pre>`)}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function saveView(){const ps=await api('projects?limit=200');document.getElementById('content').innerHTML=`<div class="page-head"><div><h1>保存记忆</h1><p>把值得延续的上下文保存成一张可跨 Agent 恢复的记忆卡。</p></div></div><section class="card form-card"><h2>一键保存聊天记忆</h2><p class="lead">粘贴聊天片段即可；通过 Agent / MCP 调用时无需手动粘贴。</p><div class="form-row"><textarea id="mem" placeholder="粘贴聊天内容、关键决定、任务进展或下一步…"></textarea></div><div class="form-row"><input id="title" placeholder="标题（可留空）"><select id="cat"><option value="auto">自动分类</option>${Object.entries(CATS).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div class="form-row"><input id="tags" placeholder="标签，用逗号分隔"><select id="saveProject"><option value="">不归入项目</option>${ps.map(p=>`<option value="${esc(p.project_id)}">${esc(p.project_id)} · ${esc(p.name)}</option>`).join('')}</select><button class="btn" onclick="saveNow()">保存</button></div><div class="file-drop"><input id="files" type="file" multiple><div class="helper" style="margin-top:7px">可以同时保存 PDF、Word、图片、CSV、代码、日志等附件。网页单附件上限 48 MB。</div></div><div id="saved" style="margin-top:14px"></div></section>`}
async function b64file(f){if(f.size>48*1024*1024)throw Error(`${f.name} 超过网页单附件 48MB 限制，请用 MCP/CLI 直接附加本地文件。`);const u=new Uint8Array(await f.arrayBuffer());let bin='';for(let i=0;i<u.length;i+=0x8000)bin+=String.fromCharCode(...u.subarray(i,i+0x8000));return btoa(bin)}
async function uploadFiles(mid,fl){let n=0;for(const f of Array.from(fl||[])){const data_base64=await b64file(f);await api(`memories/${encodeURIComponent(mid)}/attachments`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:f.name,mime_type:f.type||'application/octet-stream',data_base64})});n++}return n}
async function saveNow(){const out=document.getElementById('saved');try{const text=mem.value.trim();if(!text)throw Error('请输入要保存的内容');const j=await api('memories',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:text,title:title.value||null,category:cat.value,tags:tags.value.split(',').map(x=>x.trim()).filter(Boolean),source_agent:'Memory Box UI',project_id:saveProject.value||null})});const n=await uploadFiles(j.memory_id,files.files);out.innerHTML=`<div class="notice"><b class="ok">已保存 ${esc(j.memory_id)}</b> · ${esc(j.category_label)}${n?` · ${n} 个附件`:''}<br><span class="helper">现在可以在任意已连接 Agent 中恢复它。</span></div>`;toastMsg('记忆已保存')}catch(e){out.innerHTML=`<div class="notice danger-text">${esc(e.message)}</div>`}}
async function agentsView(){const d=await api('agents');document.getElementById('content').innerHTML=`<div class="page-head"><div><h1>Agent 连接</h1><p>通过 MCP 与本地 Agent 共享同一个 Memory Box。</p></div><button class="btn" onclick="connectAll()">一键连接检测到的 Agent</button></div><section class="card section-card"><div class="notice">Memory Box 优先使用 MCP。无法直接访问本机 localhost 的 Web Agent，请使用 Browser Bridge 或平台允许的远程连接方式。</div><div style="margin-top:10px">${d.map(a=>`<div class="agent-row"><div><div class="agent-name">${esc(a.name)}</div><div class="agent-meta">${esc(a.mode)} · ${a.detected?'<span class="ok">已检测</span>':'未检测'}</div></div><button class="btn secondary small" onclick="connectAgent('${a.key}')">连接 / 查看</button></div>`).join('')}</div></section>`}
async function connectAll(){try{const j=await api('agents/connect-all',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});showModal(`<h2>连接结果</h2><pre>${esc(JSON.stringify(j,null,2))}</pre>`)}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function connectAgent(k){try{const j=await api('agents/connect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:k})});showModal(`<h2>连接结果</h2><pre>${esc(JSON.stringify(j,null,2))}</pre>`)}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function syncView(){const [eps,det,lan,ident]=await Promise.all([api('sync/endpoints'),api('sync/detect'),api('lan/status'),api('device/identity')]);document.getElementById('content').innerHTML=`<div class="page-head"><div><h1>设备同步</h1><p>在可信设备之间同步加密记忆与附件。</p></div></div><div class="two-col"><section class="card section-card"><div class="section-card-head"><h3 class="section-title">本机身份</h3><span class="chip lock">E2EE</span></div><div class="helper">设备 ${esc(ident.device_id)}</div><pre>${esc(ident.fingerprint)}</pre><div class="helper">首次信任另一台电脑时，请在两台设备上核对完整指纹。</div></section><section class="card section-card"><div class="section-card-head"><h3 class="section-title">局域网直传</h3><span class="chip">一次性配对码</span></div><div>${lan.active?`<div class="ok">接收已开启 · 配对码 <b style="font-size:22px">${esc(lan.code)}</b></div><div class="helper">端口 ${lan.port} · 剩余 ${lan.expires_in_seconds}s</div>`:'<div class="helper">当前未开启局域网接收。</div>'}</div><div class="page-actions" style="margin-top:16px"><button class="btn small" onclick="lanStart()">开启 5 分钟接收</button><button class="btn secondary small" onclick="lanDiscover()">发现设备</button><button class="btn secondary small" onclick="lanStop()">停止</button></div><div id="lanPeers" style="margin-top:12px"></div></section></div><section class="card section-card" style="margin-top:16px"><div class="section-card-head"><h3 class="section-title">云同步文件夹</h3><span class="helper">新端点默认端到端加密</span></div><div class="form-row"><select id="syncProvider"><option value="baidu-netdisk">百度网盘 / Baidu Netdisk</option><option value="onedrive">OneDrive</option><option value="nutstore">坚果云</option><option value="syncthing">Syncthing</option><option value="nas">NAS / 网络共享</option><option value="generic-folder">其他同步文件夹</option></select><input id="syncPath" placeholder="同步目录，例如 D:\BaiduNetdisk\MemoryBox"><button class="btn" onclick="addSync()">添加</button></div>${det.length?`<div class="helper" style="margin-top:14px">检测到的候选目录</div>${det.slice(0,5).map(x=>`<div class="agent-row"><div><div class="agent-name">${esc(x.provider_label)}</div><div class="agent-meta">${esc(x.path)}</div></div><button class="btn secondary small" onclick="useDetected('${esc(x.provider)}','${esc(x.path).replace(/'/g,"\\'")}')">使用</button></div>`).join('')}`:''}<div class="helper" style="margin-top:18px">已配置端点</div>${eps.length?eps.map(e=>`<div class="agent-row"><div><div class="agent-name">${esc(e.name)}</div><div class="agent-meta">${esc(e.provider_label)} · ${esc(e.root_path)} · ${e.available?'<span class="ok">可用</span>':'<span class="warn">目录不可用</span>'} · ${e.e2ee?'<span class="ok">E2EE</span>':'<span class="warn">旧版明文</span>'}</div></div><div class="page-actions"><button class="btn secondary small" onclick="syncSend('${e.endpoint_id}')">发送</button><button class="btn secondary small" onclick="syncPull('${e.endpoint_id}')">接收</button><button class="btn secondary small" onclick="syncDevices('${e.endpoint_id}')">设备</button><button class="btn danger small" onclick="syncRemove('${e.endpoint_id}')">移除</button></div></div>`).join(''):'<div class="empty"><h3>尚未配置同步目录</h3><div>添加百度网盘、OneDrive、NAS 或任意同步文件夹。</div></div>'}</section>`}
function useDetected(provider,path){syncProvider.value=provider;syncPath.value=path}
async function addSync(){try{const j=await api('sync/add',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:syncProvider.value,path:syncPath.value,encryption_mode:'e2ee'})});toastMsg('同步端点已添加');showModal(`<h2>同步端点已添加</h2><pre>${esc(JSON.stringify(j,null,2))}</pre>`);syncView()}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function syncSend(id){if(!confirm('把当前未归档记忆和附件加密发布到这个同步端点？'))return;try{const j=await api('sync/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint_id:id})});showModal(`<h2>发送完成</h2><pre>${esc(JSON.stringify(j,null,2))}</pre>`)}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function syncPull(id){try{const j=await api('sync/pull',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint_id:id})});showModal(`<h2>接收结果</h2><pre>${esc(JSON.stringify(j,null,2))}</pre>`)}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function syncDevices(id){try{const j=await api(`sync/devices?endpoint_id=${encodeURIComponent(id)}`);showModal(`<h2>可信设备</h2><div class="helper">只有核对指纹并明确授权的设备才能解密未来同步包。</div>${j.map(d=>`<div class="agent-row"><div><div class="agent-name">${esc(d.device_name||d.device_id)}</div><div class="agent-meta">${esc(d.device_id)}${d.is_local?' · 本机':''}</div><div class="agent-meta code">${esc(d.e2ee_fingerprint||'不支持 E2EE')}</div></div>${d.is_local?'':d.trusted?`<button class="btn danger small" onclick="untrustDevice('${id}','${esc(d.device_id)}')">撤销</button>`:`<button class="btn small" onclick="trustDevice('${id}','${esc(d.device_id)}','${esc(d.e2ee_fingerprint||'')}')">信任</button>`}</div>`).join('')||'<div class="empty">还没有发现其他设备。</div>'}`)}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function trustDevice(endpoint,device,fp){if(!fp){alert('该设备没有 E2EE 公钥');return}if(!confirm('请先在另一台电脑上核对完整指纹：\n\n'+fp+'\n\n确认一致后继续。'))return;const j=await api('sync/trust',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint_id:endpoint,device_id:device,expected_fingerprint:fp})});toastMsg('已信任设备');showModal(`<pre>${esc(JSON.stringify(j,null,2))}</pre>`)}
async function untrustDevice(endpoint,device){if(!confirm('撤销后，未来同步包将不再为这台设备封装解密密钥。'))return;await api('sync/untrust',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint_id:endpoint,device_id:device})});toastMsg('已撤销信任');closeModal()}
async function syncRemove(id){if(!confirm('只移除此同步配置？云端文件不会被删除。'))return;await api('sync/remove',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint_id:id})});syncView()}
async function lanStart(){try{const j=await api('lan/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ttl:300})});showModal(`<h2>接收已开启</h2><div style="font-size:38px;font-weight:700;letter-spacing:3px;margin:16px 0">${esc(j.code)}</div><div class="helper">这个配对码 5 分钟内有效。</div>`);syncView()}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function lanStop(){await api('lan/stop',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});syncView()}
async function lanDiscover(){try{const peers=await api('lan/discover');const el=document.getElementById('lanPeers');el.innerHTML=peers.length?peers.map(p=>`<div class="agent-row"><div><div class="agent-name">${esc(p.device_name)}</div><div class="agent-meta">${esc(p.host)}:${p.port}</div></div><button class="btn secondary small" onclick="promptLanSend('${esc(p.host)}',${p.port})">发送全部</button></div>`).join(''):'<div class="helper">未发现正在配对的 Memory Box。</div>'}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function promptLanSend(host,port){const code=prompt('输入对方显示的 6 位配对码');if(!/^\d{6}$/.test(code||''))return;try{const j=await api('lan/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({host,port,code})});showModal(`<h2>发送完成</h2><pre>${esc(JSON.stringify(j,null,2))}</pre>`)}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function insuranceView(){const [st,health,allEps]=await Promise.all([api('insurance/status'),api('insurance/health'),api('sync/endpoints')]);const eps=allEps.filter(e=>e.e2ee);const last=st.last_run||{};document.getElementById('content').innerHTML=`<div class="page-head"><div><h1>自动保险</h1><p>确认“如果今天这台电脑坏了，我还能不能完整恢复”。</p></div><button class="btn secondary" onclick="healthCheck(true)">深度自检</button></div><section class="card health-banner"><div class="health-orb ${healthClass(health.status)}">${esc(health.status)}</div><div><h2 style="margin:0 0 8px;font-size:22px">${health.recoverable_if_recovery_code_available?'恢复链已就绪':'恢复链需要处理'}</h2><div class="helper">这项检查不会读取或保存恢复码。恢复码是否仍在你手里，需要你本人做本地验证。</div>${health.blockers?.length?`<div class="danger-text" style="margin-top:12px"><b>阻塞项</b><ul>${health.blockers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${health.warnings?.length?`<div class="warn" style="margin-top:12px"><b>提醒</b><ul>${health.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<div class="page-actions" style="margin-top:14px"><button class="btn secondary small" onclick="verifyBackup()">验证最新快照</button></div><div id="healthResult" style="margin-top:10px"></div></div></section><div class="two-col" style="margin-top:16px"><section class="card form-card"><h2>自动加密保险</h2><p class="lead">按周期把整个记忆库、SQLite 快照和托管附件加密保存到同步端点。</p>${eps.length?`<div class="form-row"><select id="insuranceEndpoint">${eps.map(e=>`<option value="${esc(e.endpoint_id)}" ${st.endpoint_id===e.endpoint_id?'selected':''}>${esc(e.name)} · ${esc(e.provider_label)}</option>`).join('')}</select></div><div class="form-row"><input id="insuranceHours" type="number" min="1" max="720" value="${st.interval_hours||24}" title="间隔（小时）"><input id="insuranceRetention" type="number" min="2" max="90" value="${st.retention||7}" title="保留份数"></div><div class="page-actions" style="margin-top:14px"><button class="btn" onclick="configureInsurance()">启用 / 更新</button><button class="btn secondary" onclick="runInsurance()">立即备份</button><button class="btn danger" onclick="disableInsurance()">停用</button></div>`:'<div class="notice">还没有可用的 E2EE 同步端点。先到“设备同步”添加百度网盘 / OneDrive / NAS。</div>'}<div class="helper" style="margin-top:14px">当前：${st.enabled?'已启用':'未启用'}${last.created_at?` · 上次 ${esc(last.created_at)} · ${esc(last.status)}`:''}</div><div id="insuranceAction" style="margin-top:12px"></div></section><section class="card form-card"><h2>恢复码自检</h2><p class="lead">只验证恢复文件与恢复码是否配对，不会替换设备身份。</p><div class="form-row"><input id="insuranceRecoveryFile" type="file" accept=".mbxrecovery"></div><div class="form-row"><input id="insuranceRecoveryCode" type="password" placeholder="MBR1-... 恢复码"></div><button class="btn" onclick="verifyRecoveryCode()">本地验证</button><div id="recoveryVerifyResult" style="margin-top:12px"></div></section></div>`}
async function configureInsurance(){try{const j=await api('insurance/configure',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint_id:insuranceEndpoint.value,interval_hours:Number(insuranceHours.value||24),retention:Number(insuranceRetention.value||7),deep_verify:true})});insuranceAction.innerHTML=`<div class="notice ok">自动保险已启用 · 每 ${j.interval_hours} 小时 · 保留 ${j.retention} 份</div>`}catch(e){insuranceAction.innerHTML=`<div class="notice danger-text">${esc(e.message)}</div>`}}
async function disableInsurance(){try{await api('insurance/disable',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});insuranceAction.innerHTML='<div class="notice">自动保险已停用，已有加密备份不会删除。</div>'}catch(e){insuranceAction.innerHTML=`<div class="notice danger-text">${esc(e.message)}</div>`}}
async function runInsurance(){try{insuranceAction.innerHTML='<div class="helper">正在生成完整加密快照…</div>';const j=await api('insurance/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({force:true})});insuranceAction.innerHTML=`<div class="notice ok">完成：${j.memory_count} 条记忆 · ${j.attachment_count} 个附件</div>`}catch(e){insuranceAction.innerHTML=`<div class="notice danger-text">${esc(e.message)}</div>`}}
async function healthCheck(deep){try{const j=await api('insurance/health?deep='+(deep?'1':'0'));showModal(`<h2>灾难恢复自检</h2><pre>${esc(JSON.stringify(j,null,2))}</pre>`)}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function verifyBackup(){try{const j=await api('insurance/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});showModal(`<h2 class="ok">最新保险快照验证通过</h2><p>${j.memory_count} 条记忆 · ${j.attachment_count} 个附件</p><pre>${esc(JSON.stringify(j,null,2))}</pre>`)}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function verifyRecoveryCode(){try{const f=insuranceRecoveryFile.files[0];if(!f)throw Error('请选择 .mbxrecovery 文件');const data_base64=await b64file(f);const j=await api('recovery/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data_base64,recovery_code:insuranceRecoveryCode.value})});insuranceRecoveryCode.value='';recoveryVerifyResult.innerHTML=`<div class="notice ok">验证成功 · 指纹 ${esc(j.fingerprint)}</div>`}catch(e){insuranceRecoveryCode.value='';recoveryVerifyResult.innerHTML=`<div class="notice danger-text">${esc(e.message)}</div>`}}
async function recoveryView(){const [st,eps]=await Promise.all([api('recovery/status'),api('sync/endpoints')]);document.getElementById('content').innerHTML=`<div class="page-head"><div><h1>灾难恢复</h1><p>管理设备身份保险箱。恢复码始终只由你本人保管。</p></div></div><div class="two-col"><section class="card section-card"><div class="section-card-head"><h3 class="section-title">当前设备身份</h3><span class="chip">X25519</span></div><div class="helper">设备 ${esc(st.device_id)}</div><pre>${esc(st.fingerprint)}</pre><div class="metric"><span class="metric-label">已创建恢复包</span><span class="metric-value">${st.recovery_kits_created}</span></div><div class="metric"><span class="metric-label">执行过恢复</span><span class="metric-value">${st.recoveries_performed}</span></div></section><section class="card form-card"><h2>创建恢复保险箱</h2><p class="lead">生成加密的 .mbxrecovery 文件和一次性显示的恢复码。文件可放百度网盘，恢复码应离线保存。</p><button class="btn" onclick="createRecovery()">生成恢复文件</button><div id="recoveryCreateResult" style="margin-top:14px"></div></section></div><section class="card form-card" style="margin-top:16px"><h2>恢复旧电脑身份</h2><p class="lead">在新电脑选择 .mbxrecovery，并输入离线保存的恢复码。恢复码只提交给本机 Memory Box。</p><div class="form-row"><input id="recoveryFile" type="file" accept=".mbxrecovery"><input id="recoveryCode" type="password" placeholder="MBR1-... 恢复码"></div><div style="margin:12px 0"><label class="helper"><input id="replaceIdentity" type="checkbox"> 本机已有不同身份时允许替换（会先备份现有私钥）</label></div><button class="btn" onclick="restoreRecovery()">验证并恢复</button><div id="recoveryRestoreResult" style="margin-top:12px"></div></section>${eps.length?`<section class="card form-card" style="margin-top:16px"><h2>备份恢复文件</h2><p class="lead">这里只上传加密的 .mbxrecovery，不上传恢复码。</p><div class="form-row"><input id="recoveryCloudFile" placeholder="本机 .mbxrecovery 文件路径"><select id="recoveryEndpoint">${eps.map(e=>`<option value="${esc(e.endpoint_id)}">${esc(e.name)} · ${esc(e.provider_label)}</option>`).join('')}</select><button class="btn secondary" onclick="backupRecovery()">备份</button></div><div id="recoveryBackupResult" style="margin-top:10px"></div></section>`:''}`}
async function createRecovery(){try{const j=await api('recovery/create',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});recoveryCreateResult.innerHTML=`<div class="notice"><b class="ok">恢复文件已创建</b><br><a href="${esc(j.download_url)}">下载 ${esc(j.filename)}</a><div class="helper" style="margin-top:10px">恢复码只显示这一次，不要贴进任何 AI 对话。</div><pre style="font-size:17px;font-weight:700">${esc(j.recovery_code)}</pre><div class="helper">SHA-256: ${esc(j.sha256)}</div></div>`}catch(e){recoveryCreateResult.innerHTML=`<div class="notice danger-text">${esc(e.message)}</div>`}}
async function restoreRecovery(){try{const f=recoveryFile.files[0];if(!f)throw Error('请选择 .mbxrecovery 文件');const data_base64=await b64file(f);const j=await api('recovery/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:f.name,data_base64,recovery_code:recoveryCode.value,replace_existing:replaceIdentity.checked})});recoveryCode.value='';recoveryRestoreResult.innerHTML=`<div class="notice ok">恢复成功 · 设备 ${esc(j.device_id)} · 指纹 ${esc(j.fingerprint)}</div>`}catch(e){recoveryCode.value='';recoveryRestoreResult.innerHTML=`<div class="notice danger-text">${esc(e.message)}</div>`}}
async function backupRecovery(){try{const j=await api('recovery/backup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:recoveryCloudFile.value,endpoint_id:recoveryEndpoint.value})});recoveryBackupResult.innerHTML=`<div class="notice ok">已备份：${esc(j.path)}</div>`}catch(e){recoveryBackupResult.innerHTML=`<div class="notice danger-text">${esc(e.message)}</div>`}}
function transferView(){document.getElementById('content').innerHTML=`<div class="page-head"><div><h1>迁移</h1><p>把一个 AI 工作现场完整搬到另一台电脑。</p></div></div><div class="two-col"><section class="card form-card"><h2>导出会话包</h2><p class="lead">生成 .mboxpack，包含记忆、附件、离线复现页和 Resume Context。</p><div class="form-row"><select id="exscope"><option value="all">整个记忆库</option><option value="category">当前分类</option></select></div><button class="btn" onclick="exportPack()">导出 .mboxpack</button><div id="exresult" style="margin-top:12px"></div></section><section class="card form-card"><h2>导入会话包</h2><p class="lead">导入前验证格式与 SHA-256；ID 冲突不会覆盖本机内容。</p><div class="form-row"><input id="impfile" type="file" accept=".mboxpack,.zip"></div><button class="btn" onclick="importPack()">验证并导入</button><div id="impresult" style="margin-top:12px"></div></section></div>`}
async function exportPack(){try{const j=await api('export-pack',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({category:exscope.value==='category'?currentCat:null})});exresult.innerHTML=`<div class="notice ok">已生成 ${esc(j.filename)} · ${j.memory_count} 条记忆。<br><a href="/api/exports/${encodeURIComponent(j.filename)}" download>下载迁移包</a></div>`}catch(e){exresult.innerHTML=`<div class="notice danger-text">${esc(e.message)}</div>`}}
async function exportSingle(id){try{const j=await api('export-pack',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({memory_ids:[id]})});location.href=`/api/exports/${encodeURIComponent(j.filename)}`}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function importPack(){const f=impfile.files[0];if(!f){impresult.innerHTML='<div class="notice">请选择 .mboxpack 文件</div>';return}if(f.size>64*1024*1024){impresult.innerHTML='<div class="notice">浏览器单包暂限 64 MB；更大的包请双击 .mboxpack。</div>';return}try{const bytes=new Uint8Array(await f.arrayBuffer());let bin='';for(let i=0;i<bytes.length;i+=0x8000)bin+=String.fromCharCode(...bytes.subarray(i,i+0x8000));const j=await api('import-pack',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:f.name,data_base64:btoa(bin)})});impresult.innerHTML=`<div class="notice ok">导入完成：新增 ${j.imported}，跳过 ${j.skipped}，冲突重编号 ${j.remapped}${j.transfer_id?`<br><a target="_blank" href="/api/replay/${encodeURIComponent(j.transfer_id)}">打开对话复现页</a>`:''}</div>`}catch(e){impresult.innerHTML=`<div class="notice danger-text">${esc(e.message)}</div>`}}
async function settingsView(){const mode=localStorage.getItem('memorybox-theme')||'auto';const semantic=await api('semantic/status');let desktop=null;try{if(window.pywebview?.api?.get_desktop_status)desktop=await window.pywebview.api.get_desktop_status()}catch{};const ds=desktop?.settings||{};document.getElementById('content').innerHTML=`<div class="page-head"><div><h1>设置</h1><p>控制外观、桌面行为与本地偏好。</p></div></div><section class="card settings-list"><div class="setting-row"><div><div class="setting-title">外观</div><div class="setting-desc">跟随系统，或固定浅色 / 深色。</div></div><div class="segmented">${['light','dark','auto'].map(x=>`<button class="${mode===x?'active':''}" onclick="setTheme('${x}');settingsView()">${x==='light'?'浅色':x==='dark'?'深色':'自动'}</button>`).join('')}</div></div>${desktop?`<div class="setting-row"><div><div class="setting-title">关闭窗口</div><div class="setting-desc">关闭或最小化窗口时继续在系统托盘运行。</div></div><label class="switch-label"><input type="checkbox" ${ds.minimize_to_tray?'checked':''} onchange="desktopTray(this.checked)"> 最小化到托盘</label></div><div class="setting-row"><div><div class="setting-title">开机启动</div><div class="setting-desc">登录 ${desktop.platform==='Darwin'?'macOS':'Windows'} 后自动启动 Memory Box。</div></div><label class="switch-label"><input type="checkbox" ${ds.start_on_login?'checked':''} onchange="desktopStartup(this.checked)"> 自动启动</label></div><div class="setting-row"><div><div class="setting-title">系统通知</div><div class="setting-desc">显示导入、同步和保险完成通知。</div></div><label class="switch-label"><input type="checkbox" ${ds.notifications?'checked':''} onchange="desktopNotifications(this.checked)"> 已启用</label></div><div class="setting-row"><div><div class="setting-title">桌面模式</div><div class="setting-desc">原生窗口 · 系统托盘 · 文件拖放</div></div><div class="ok">已连接</div></div>`:`<div class="setting-row"><div><div class="setting-title">桌面模式</div><div class="setting-desc">当前运行在浏览器模式。Windows / macOS 桌面版会显示托盘与开机启动选项。</div></div><div class="helper">Web UI</div></div>`}<div class="setting-row"><div><div class="setting-title">本地向量检索</div><div class="setting-desc">${esc(semantic.detail||'所有向量都在本机计算。')}</div></div><div class="code">${esc(semantic.backend)}</div></div><div class="setting-row"><div><div class="setting-title">本地优先</div><div class="setting-desc">Memory Box UI 默认仅监听 127.0.0.1。</div></div><div class="ok">已启用</div></div><div class="setting-row"><div><div class="setting-title">当前版本</div><div class="setting-desc">Windows / macOS 桌面控制中心</div></div><div class="code">v__VERSION__</div></div></section>`}
async function desktopTray(v){try{await window.pywebview.api.set_minimize_to_tray(v);toastMsg(v?'已启用最小化到托盘':'关闭窗口将退出应用')}catch(e){toastMsg(e.message)}}
async function desktopStartup(v){try{const j=await window.pywebview.api.set_start_on_login(v);toastMsg(j.supported?(v?'已启用开机启动':'已关闭开机启动'):'当前系统不支持')}catch(e){toastMsg(e.message);settingsView()}}
async function desktopNotifications(v){try{await window.pywebview.api.set_notifications(v);toastMsg(v?'已启用系统通知':'已关闭系统通知')}catch(e){toastMsg(e.message)}}
function applyTheme(){const mode=localStorage.getItem('memorybox-theme')||'auto';const dark=mode==='dark'||(mode==='auto'&&matchMedia('(prefers-color-scheme:dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light'}
function setTheme(mode){localStorage.setItem('memorybox-theme',mode);applyTheme()}
function cycleTheme(){const now=localStorage.getItem('memorybox-theme')||'auto';setTheme(now==='auto'?'light':now==='light'?'dark':'auto');toastMsg('外观：'+(localStorage.getItem('memorybox-theme')==='auto'?'自动':localStorage.getItem('memorybox-theme')==='light'?'浅色':'深色'))}
async function openMemory(id){const [m,rel]=await Promise.all([api('memories/'+id),api('memories/'+id+'/related')]);const at=(m.attachments||[]).map(a=>`<div class="agent-row"><div><div class="agent-name">${esc(a.original_name)}</div><div class="agent-meta">${esc(a.mime_type)} · ${a.size_bytes} bytes</div></div><a class="btn secondary small" href="/api/attachments/${encodeURIComponent(a.sha256)}?memory_id=${encodeURIComponent(m.memory_id)}" target="_blank">打开</a></div>`).join('')||'<div class="helper">暂无附件</div>';showModal(`<div class="helper">${esc(m.memory_id)} · ${esc(m.category_label)} · ${esc(m.updated_at)}</div><h1 style="font-size:25px;margin:7px 0 4px">${esc(m.title)}</h1><div class="helper">来源：${esc(m.source_agent)}${m.source_uri?' · '+esc(m.source_uri):''}</div><p style="line-height:1.6">${esc(m.summary||'')}</p><pre>${esc(m.content)}</pre><h3>附件</h3>${at}<h3>相关记忆</h3>${rel.map(x=>`<div class="memory-row" onclick="openMemory('${x.memory_id}')"><div class="memory-icon">${esc(x.memory_id)}</div><div><div class="memory-title">${esc(x.title)}</div></div></div>`).join('')||'<div class="helper">暂无相关记忆</div>'}<div class="page-actions" style="margin-top:18px"><button class="btn" onclick="resumeOne('${m.memory_id}')">生成恢复上下文</button><button class="btn secondary" onclick="findDuplicates('${m.memory_id}')">查找重复</button><button class="btn secondary" onclick="exportSingle('${m.memory_id}')">导出</button></div>`)}
async function findDuplicates(id){try{const xs=await api(`memories/${id}/duplicates?limit=10`);showModal(`<h2>重复记忆建议</h2><div class="helper">只做候选识别，不会自动合并。</div>${xs.length?xs.map(x=>`<div class="memory-row"><div class="memory-icon">${esc(x.memory_id)}</div><div style="flex:1"><div class="memory-title">${esc(x.title)}</div><div class="memory-summary">相似度 ${(Number(x.score||0)*100).toFixed(0)}% · ${esc(x.reason||'')}</div></div><button class="btn secondary small" onclick="mergeDuplicatePair('${id}','${x.memory_id}')">合并</button></div>`).join(''):'<div class="notice ok">没有发现达到阈值的重复记忆。</div>'}`)}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function mergeDuplicatePair(a,b){if(!confirm(`确认合并 ${a} 与 ${b}？原记忆默认保留。`))return;try{const j=await api('dedup/merge',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({memory_ids:[a,b],archive_sources:false})});toastMsg(`已生成 ${j.memory_id}`);closeModal();openMemory(j.memory_id)}catch(e){showModal(`<pre>${esc(e.message)}</pre>`)}}
async function flag(id,f,v){await api('memories/'+id+'/flag',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({flag:f,value:v})});if(currentView==='memories')loadMemoriesData(document.getElementById('q')?.value||'')}
async function resumeOne(id){const j=await api('resume',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({memory_ids:[id]})});showModal(`<h2>Resume Context</h2><div class="helper">复制下面的内容到任意 AI Agent，即可继续。</div><pre>${esc(j.context)}</pre>`)}
function showModal(h){modalBody.innerHTML=h;modal.style.display='flex'}function closeModal(){modal.style.display='none'}
applyTheme();matchMedia('(prefers-color-scheme:dark)').addEventListener?.('change',()=>{if((localStorage.getItem('memorybox-theme')||'auto')==='auto')applyTheme()});view('home');
</script>
</body></html>'''
